public int findLargestSubstring(List<String> strings) {
    // Handle null or empty input
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Build a set of all substrings for each string
    List<Set<String>> substringSets = new ArrayList<>();
    for (String s : strings) {
        Set<String> set = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }

    // Generate candidate substrings from the first string
    String first = strings.get(0);
    Set<String> candidates = new HashSet<>();
    int firstLen = first.length();
    for (int i = 0; i < firstLen; i++) {
        for (int j = i + 1; j <= firstLen; j++) {
            String sub = first.substring(i, j);
            candidates.add(sub);
            candidates.add(new StringBuilder(sub).reverse().toString());
        }
    }

    int maxLen = 0;
    for (String candidate : candidates) {
        int candidateLen = candidate.length();
        if (candidateLen <= maxLen) {
            continue; // no need to check shorter candidates
        }
        String reverseCandidate = new StringBuilder(candidate).reverse().toString();
        boolean allContain = true;
        for (Set<String> set : substringSets) {
            if (!set.contains(candidate) && !set.contains(reverseCandidate)) {
                allContain = false;
                break;
            }
        }
        if (allContain) {
            maxLen = candidateLen;
        }
    }

    return maxLen;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest non-null string to limit candidate substrings
    String base = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            continue;
        }
        if (s.length() < minLen) {
            minLen = s.length();
            base = s;
        }
    }
    if (base == null) {
        return 0;
    }

    // Check lengths from largest to smallest
    for (int len = minLen; len >= 1; len--) {
        // Collect all unique substrings of this length from the base string
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i + len <= base.length(); i++) {
            candidates.add(base.substring(i, i + len));
        }

        // For each candidate, verify it appears (directly or reversed) in every string
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null) {
                    continue; // Treat null strings as not containing anything
                }
                if (s.indexOf(cand) == -1 && s.indexOf(rev) == -1) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

