        for (int c = 0; c < cols; c++) {
            if (grid[r][c] != '@' || visited[r][c]) continue;
            count++;
            java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
            stack.push(new int[]{r, c});
            visited[r][c] = true;
            while (!stack.isEmpty()) {
                int[] cur = stack.pop();
                int cr = cur[0], cc = cur[1];
                for (int[] d : dirs) {
                    int nr = cr + d[0];
                    int nc = cc + d[1];
                    if (nr < 0 || nr >= rows) continue;
                    if (grid[nr] == null || nc < 0 || nc >= grid[nr].length) continue;
                    if (!visited[nr][nc] && grid[nr][nc] == '@') {
                        visited[nr][nc] = true;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
    }
    return count;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    final int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    final int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    int rows = grid.length;
    int maxCols = 0;
    for (int i = 0; i < rows; i++) {
        if (grid[i] != null && grid[i].length > maxCols) {
            maxCols = grid[i].length;
        }
    }

    // Estimate maximum cells to allocate for the stack
    int maxCells = rows * maxCols;
    int[] stackR = new int[maxCells];
    int[] stackC = new int[maxCells];
    int stackTop = -1;

    int deposits = 0;

    for (int r = 0; r < rows; r++) {
        if (grid[r] == null) continue;
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] != '@') continue;

            deposits++;
            // Mark as visited
            grid[r][c] = '*';
            // Push the starting cell onto the stack
            stackR[++stackTop] = r;
            stackC[stackTop] = c;

            // Explore all connected '@' cells
            while (stackTop >= 0) {
                int curR = stackR[stackTop];
                int curC = stackC[stackTop];
                stackTop--;

                for (int d = 0; d < 8; d++) {
                    int nr = curR + dr[d];
                    int nc = curC + dc[d];

                    if (nr < 0 || nr >= rows) continue;
                    if (grid[nr] == null || nc < 0 || nc >= grid[nr].length) continue;
                    if (grid[nr][nc] != '@') continue;

                    grid[nr][nc] = '*';
                    stackR[++stackTop] = nr;
                    stackC[stackTop] = nc;
                }
            }
        }
    }

    return deposits;
}

public static int maxRegions(int N) {
    if (N < 1) {
        throw new IllegalArgumentException("Number of triangles must be at least 1");
    }
    long result = 3L * N * N - 3L * N + 2;
    if (result > Integer.MAX_VALUE || result < Integer.MIN_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) result;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non‑negative");
    }
    // Using the formula derived from the problem specification:
    // maximum regions = 2 + 3 * N * (N - 1)
    long regions = 2L + 3L * N * (N - 1);
    if (regions > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds the maximum value for int");
    }
    return (int) regions;
}

