public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Set<Integer> values = new java.util.HashSet<>();
    for (int num : numbers) {
        values.add(num);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 == 0) {
            int half = num / 2;
            // We need to ensure that the half exists in the list.
            // Additionally, we must handle the case where num == half
            // (which only happens for num == 0). For zero, there must be at
            // least one other zero to be considered a double. We can simply
            // rely on the set membership; if zero appears once, the condition
            // if (values.contains(0)) will be true, but that would incorrectly
            // count the lone zero. To avoid this, check the count of zeros.
            if (num == 0) {
                // Count zeros only if there is more than one zero.
                int zeroCount = 0;
                for (int x : numbers) {
                    if (x == 0) {
                        zeroCount++;
                        if (zeroCount > 1) {
                            break;
                        }
                    }
                }
                if (zeroCount > 1) {
                    count++;
                }
            } else {
                if (values.contains(half)) {
                    count++;
                }
            }
        }
    }
    return count;
}

