public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || paths == null) {
            return "cannot be travelled";
        }

        // Assume start[0] and end[0] represent node IDs
        if (start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }
        int startNode = start[0];
        int endNode = end[0];

        // Determine the maximum node index to size adjacency list
        int maxNode = Math.max(startNode, endNode);
        for (int[] p : paths) {
            if (p == null || p.length < 2) continue;
            maxNode = Math.max(maxNode, Math.max(p[0], p[1]));
        }

        // Build adjacency list
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= maxNode; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] p : paths) {
            if (p == null || p.length < 2) continue;
            int u = p[0];
            int v = p[1];
            if (u < 0 || v < 0 || u > maxNode || v > maxNode) continue;
            adj.get(u).add(v);
            adj.get(v).add(u); // assuming undirected paths
        }

        // BFS to check connectivity
        boolean[] visited = new boolean[maxNode + 1];
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(startNode);
        visited[startNode] = true;

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endNode) {
                return "can be travelled";
            }
            for (int nb : adj.get(cur)) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.add(nb);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // In case of any runtime issue, default to cannot be travelled
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    int dimension = start.length;
    if (dimension == 0 || dimension != end.length) {
        return "cannot be travelled";
    }

    // Helper to convert coordinate array to a string key
    java.util.function.Function<int[], String> coordToKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            sb.append(coord[i]).append(',');
        }
        return sb.toString();
    };

    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();

    // Build adjacency list from paths
    for (int[] path : paths) {
        if (path == null || path.length != dimension * 2) {
            continue; // ignore malformed path
        }
        int[] from = new int[dimension];
        int[] to = new int[dimension];
        System.arraycopy(path, 0, from, 0, dimension);
        System.arraycopy(path, dimension, to, 0, dimension);
        String fromKey = coordToKey.apply(from);
        String toKey = coordToKey.apply(to);
        adjacency.computeIfAbsent(fromKey, k -> new java.util.ArrayList<>()).add(toKey);
        adjacency.computeIfAbsent(toKey, k -> new java.util.ArrayList<>()).add(fromKey); // assuming undirected
    }

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);
    if (!adjacency.containsKey(startKey) || !adjacency.containsKey(endKey)) {
        return "cannot be travelled";
    }

    java.util.Deque<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adjacency.getOrDefault(current, java.util.Collections.emptyList());
        for (String neigh : neighbors) {
            if (!visited.contains(neigh)) {
                visited.add(neigh);
                queue.add(neigh);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
