            continue; // Skip malformed paths
        }
        int u = path[0];
        int v = path[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue; // Ignore invalid edges
        }
        adj[u].add(v);
        adj[v].add(u); // Assuming undirected paths
    }

    // Breadth-First Search
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    queue.add(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
