        }
        for (int neighbor : adj[curr]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || paths == null ||
            start.length != n || end.length != n) {
            return "cannot be travelled";
        }

        // Helper to convert coordinate array to string key
        java.util.function.Function<int[], String> coordKey = coord -> {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < coord.length; i++) {
                if (i > 0) sb.append('#');
                sb.append(coord[i]);
            }
            return sb.toString();
        };

        // Quick check if start equals end
        boolean same = true;
        for (int i = 0; i < n; i++) {
            if (start[i] != end[i]) {
                same = false;
                break;
            }
        }
        if (same) return "can be travelled";

        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

        // Populate graph from paths
        for (int[] path : paths) {
            if (path == null) continue;
            // Path is expected to have 2 * n integers: first n are start, next n are end
            if (path.length != 2 * n) continue;
            int[] p1 = new int[n];
            int[] p2 = new int[n];
            System.arraycopy(path, 0, p1, 0, n);
            System.arraycopy(path, n, p2, 0, n);
            String key1 = coordKey.apply(p1);
            String key2 = coordKey.apply(p2);
            graph.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
            graph.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
        }

        String startKey = coordKey.apply(start);
        String endKey = coordKey.apply(end);

        if (!graph.containsKey(startKey) || !graph.containsKey(endKey)) {
            // If start or end not present in graph but start==end is already checked
            return "cannot be travelled";
        }

        // BFS to find path
        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.offer(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String current = queue.poll();
            if (current.equals(endKey)) {
                return "can be travelled";
            }
            java.util.List<String> neighbors = graph.getOrDefault(current, java.util.Collections.emptyList());
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.offer(nb);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // In case of any unexpected errors, default to cannot be travelled
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0) throw new IllegalArgumentException("Dimension n must be positive");
        if (start == null || end == null || paths == null)
            throw new IllegalArgumentException("Arguments cannot be null");
        if (start.length != n || end.length != n)
            throw new IllegalArgumentException("Start and end coordinates must match dimension n");
        // If start and end are same, trivially reachable
        boolean same = true;
        for (int i = 0; i < n; i++) {
            if (start[i] != end[i]) { same = false; break; }
        }
        if (same) return "can be travelled";

        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
        // Helper to convert coordinate array to a unique string key
        java.util.function.Function<int[], String> coordToKey = coord -> {
            StringBuilder sb = new StringBuilder();
            sb.append(coord[0]);
            for (int i = 1; i < coord.length; i++) {
                sb.append(',').append(coord[i]);
            }
            return sb.toString();
        };

        // Build graph from paths
        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) continue; // skip malformed entries
            int[] a = new int[n], b = new int[n];
            System.arraycopy(path, 0, a, 0, n);
            System.arraycopy(path, n, b, 0, n);
            String ka = coordToKey.apply(a);
            String kb = coordToKey.apply(b);
            graph.computeIfAbsent(ka, k -> new java.util.ArrayList<>()).add(kb);
            graph.computeIfAbsent(kb, k -> new java.util.ArrayList<>()).add(ka);
        }

        String startKey = coordToKey.apply(start);
        String endKey = coordToKey.apply(end);

        // Ensure start and end are present in graph even if isolated
        graph.computeIfAbsent(startKey, k -> new java.util.ArrayList<>());
        graph.computeIfAbsent(endKey, k -> new java.util.ArrayList<>());

        java.util.Set<String> visited = new java.util.HashSet<>();
        java.util.Deque<String> stack = new java.util.ArrayDeque<>();
        stack.push(startKey);
        visited.add(startKey);

        while (!stack.isEmpty()) {
            String cur = stack.pop();
            if (cur.equals(endKey)) return "can be travelled";
            for (String nei : graph.getOrDefault(cur, java.util.Collections.emptyList())) {
                if (!visited.contains(nei)) {
                    visited.add(nei);
                    stack.push(nei);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // For any unexpected error, treat as not reachable
        return "cannot be travelled";
    }
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words must not be null.");
    }
    word1 = word1.trim();
    word2 = word2.trim();
    if (word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Input words must not be empty.");
    }
    int lenSum = word1.length() + word2.length();
    // Count distinct letters present in both words
    java.util.Set<Character> set1 = new java.util.HashSet<>();
    for (char c : word1.toCharArray()) set1.add(c);
    java.util.Set<Character> set2 = new java.util.HashSet<>();
    for (char c : word2.toCharArray()) set2.add(c);
    set1.retainAll(set2);
    int commonDistinct = set1.size();
    int numerator = commonDistinct * 2; // each common letter counted twice
    if (numerator == 0) {
        return String.format("appx(%s, %s) = 0", word1, word2);
    }
    if (numerator == lenSum) {
        return String.format("appx(%s, %s) = 1", word1, word2);
    }
    int gcd = java.lang.Math.abs(gcd(numerator, lenSum));
    int reducedNum = numerator / gcd;
    int reducedDen = lenSum / gcd;
    return String.format("appx(%s, %s) = %d/%d", word1, word2, reducedNum, reducedDen);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Input date string cannot be null or empty");
    }
    try {
        java.time.format.DateTimeFormatter parser =
            java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.US);
        java.time.LocalDate localDate = java.time.LocalDate.parse(date.trim(), parser);

        java.time.format.DateTimeFormatter monthFormatter =
            java.time.format.DateTimeFormatter.ofPattern("MMMM", java.util.Locale.US);
        java.time.format.DateTimeFormatter weekdayFormatter =
            java.time.format.DateTimeFormatter.ofPattern("EEEE", java.util.Locale.US);

        String monthName = monthFormatter.format(localDate);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = weekdayFormatter.format(localDate);

        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format. Expected format: MM dd yyyy", e);
    }
}

