        String monthName = localDate.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String weekday = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return String.format("%s %d, %d is a %s", monthName, day, year, weekday);
    } catch (Exception e) {
        return "Invalid date";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null.");
    }
    DateTimeFormatter parser = DateTimeFormatter.ofPattern("MM dd yyyy");
    try {
        LocalDate localDate = LocalDate.parse(date.trim(), parser);
        String monthName = localDate.getMonth().getDisplayName(TextStyle.FULL, Locale.ENGLISH);
        int dayOfMonth = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = localDate.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.ENGLISH);
        return String.format("%s %d, %d is a %s", monthName, dayOfMonth, year, weekday);
    } catch (DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format. Expected format is \"MM dd yyyy\".", e);
    }
}

