public double trimMean(int[] arr) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    int n = arr.length;
    if (n == 0) {
        throw new IllegalArgumentException("Input array cannot be empty.");
    }
    // Determine number of elements to remove from each end (5%).
    int trimCount = (int) Math.floor(n * 0.05);
    // Copy and sort the array to identify the smallest and largest 5%.
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    // Sum the remaining elements.
    long sum = 0;
    for (int i = trimCount; i < n - trimCount; i++) {
        sum += sorted[i];
    }
    int remaining = n - 2 * trimCount;
    return (double) sum / remaining;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int drop = n / 20; // floor of 5%
    if (drop * 2 >= n) {
        return 0.0;
    }
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = drop; i < n - drop; i++) {
        sum += arr[i];
    }
    return sum / (double) (n - 2 * drop);
}

public double trimMean(int[] arr) {
    // Handle null or empty input
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    try {
        int n = arr.length;
        // Number of elements to trim from each side (5% of array length)
        int cut = (int)Math.floor(n * 0.05);
        java.util.Arrays.sort(arr);
        // Sum the retained elements
        double sum = 0.0;
        int start = cut;
        int end = n - cut; // exclusive
        if (end <= start) {
            // No elements remain after trimming; return 0.0 to avoid division by zero
            return 0.0;
        }
        for (int i = start; i < end; i++) {
            sum += arr[i];
        }
        int remaining = end - start;
        return sum / remaining;
    } catch (Exception e) {
        // In case of any unexpected runtime exception, return 0.0
        return 0.0;
    }
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int[] sorted = new int[n];
    System.arraycopy(arr, 0, sorted, 0, n);
    java.util.Arrays.sort(sorted);
    int trimCount = (int) Math.floor(n * 0.05);
    long sum = 0L;
    int start = trimCount;
    int end = n - trimCount; // exclusive
    for (int i = start; i < end; i++) {
        sum += sorted[i];
    }
    int kept = end - start;
    if (kept <= 0) {
        return 0.0;
    }
    return sum / (double) kept;
}

