    int k = n / 20; // number of elements to trim from each end
    // Clone and sort the array to avoid modifying the original
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    int count = n - 2 * k;
    return (double) sum / count;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    if (k <= 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += k;
        freq[r]++;
    }
    if (freq[0] % 2 != 0) return false;
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) return false;
    for (int r = 1; r < k / 2; r++) {
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        throw new NullPointerException("Input array cannot be null");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Divisor k must be positive");
    }

    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair all elements
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = Math.floorMod(num, k); // handles negative numbers correctly
        freq[r]++;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // Check other remainders
    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (r == complement) { // already handled when k even
            continue;
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        throw new IllegalArgumentException("array must not be null and k must be positive");
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair all elements if odd length
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        count[r]++;
    }
    // remainder 0 must have even count
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k even, remainder k/2 must have even count
    if (k % 2 == 0) {
        int mid = k / 2;
        if (count[mid] % 2 != 0) {
            return false;
        }
    }
    // Check pairs of remainders r and k-r
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled when k even
            continue;
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || arr.length == 0 || arr.length % 2 != 0 || k <= 0) {
        return false;
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int mod = ((num % k) + k) % k; // ensure non-negative remainder
        freq[mod]++;
    }

    // Check remainder 0 pairs
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, check remainder k/2 pairs
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }

    // Check all other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = (k - r) % k;
        if (freq[r] != freq[complement]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Handle null or invalid inputs
    if (arr == null) {
        return false;
    }
    int n = arr.length;
    // Must have an even number of elements to form pairs
    if (n % 2 != 0) {
        return false;
    }
    // k must be a positive integer
    if (k <= 0) {
        return false;
    }

    // Frequency array for remainders modulo k
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k; // Convert negative remainder to positive
        }
        freq[r]++;
    }

    // Remainder 0: pairs must be formed only within this group
    if (freq[0] % 2 != 0) {
        return false;
    }

    // Main loop: check each remainder r with its complement (k - r)
    int half = k / 2;
    for (int r = 1; r < half; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }

    // If k is even, remainder k/2 also needs an even count
    if (k % 2 == 0) {
        if (freq[half] % 2 != 0) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        return 0;
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple length must equal n");
    }

    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length != 2) {
                throw new IllegalArgumentException("Each edge must contain exactly two nodes");
            }
            int u = e[0], v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                throw new IllegalArgumentException("Edge node out of bounds");
            }
            adj[u].add(v);
            adj[v].add(u);
        }
    } else {
        if (n > 1) {
            // Tree with multiple nodes but no edges: invalid input
            return 0;
        }
    }

    // Iterative DFS to process nodes in post-order
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    parent[0] = -2; // mark root visited
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei : adj[node]) {
            if (parent[nei] == -1) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }

    int total = 0;
    int[] subtreeHas = new int[n];
    for (int i = idx - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nei : adj[node]) {
            if (parent[nei] == node && subtreeHas[nei] == 1) {
                has = true;
                total += 2; // go to child and back
            }
        }
        subtreeHas[node] = has ? 1 : 0;
    }
    return total;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    @SuppressWarnings("unchecked")
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] ans = new int[1];
    dfs(0, -1, graph, ans, hasApple);
    return ans[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, int[] ans, boolean[] hasApple) {
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        boolean childHas = dfs(nei, node, graph, ans, hasApple);
        if (childHas) {
            ans[0] += 2; // cost to go to child and back
            has = true;
        }
    }
    return has;
}

