public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n) {
        return 0;
    }
    // Build adjacency list
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length < 2) continue;
            int u = e[0];
            int v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            adj[u].add(v);
            adj[v].add(u);
        }
    }
    // Use iterative DFS to get order and parent array
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -2); // -2 means unvisited
    int[] order = new int[n];
    int idx = 0;
    int[] stack = new int[n];
    int sp = 0;
    stack[sp++] = 0;
    parent[0] = -1;
    while (sp > 0) {
        int node = stack[--sp];
        order[idx++] = node;
        for (int nb : adj[node]) {
            if (parent[nb] == -2) {
                parent[nb] = node;
                stack[sp++] = nb;
            }
        }
    }
    boolean[] needed = new boolean[n];
    int result = 0;
    for (int i = idx - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nb : adj[node]) {
            if (nb != parent[node] && needed[nb]) {
                has = true;
                break;
            }
        }
        needed[node] = has;
        if (node != 0 && has) {
            result += 2;
        }
    }
    return result;
}

