public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    final int MAX_CHAR = 65535;
    int[] count = new int[MAX_CHAR + 1];
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        count[c]++; // char is automatically widened to int for indexing
    }

    StringBuilder result = new StringBuilder(n);
    int remaining = n;

    while (remaining > 0) {
        // Ascending phase: pick smallest > last appended
        for (int i = 0; i <= MAX_CHAR && remaining > 0; i++) {
            if (count[i] > 0) {
                result.append((char) i);
                count[i]--;
                remaining--;
            }
        }

        // Descending phase: pick largest < last appended
        for (int i = MAX_CHAR; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                result.append((char) i);
                count[i]--;
                remaining--;
            }
        }
    }

    return result.toString();
}

