public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or insufficient length
    if (cost == null || cost.length == 0) {
        return 0; // No steps to climb, cost is zero
    }

    int n = cost.length;
    // If there's one or two steps, we can reach the top without paying any cost
    if (n <= 2) {
        return 0;
    }

    // Use two variables to store the minimum cost to reach the two previous steps
    int prev2 = 0; // Min cost to reach step 0
    int prev1 = 0; // Min cost to reach step 1

    for (int i = 2; i <= n; i++) {
        // cost[i-1] is the cost of stepping onto the (i-1)-th step
        int current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);

        // Update the two previous values for the next iteration
        prev2 = prev1;
        prev1 = current;
    }
    // prev1 now holds the min cost to reach the top
    return prev1;
}

