    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    // If there's only one step, you could start at step 1 (outside the array) and finish immediately.
    if (n == 1) {
        return 0;
    }
    int prev2 = 0; // dp[0]
    int prev1 = 0; // dp[1]
    int curr = 0;
    for (int i = 2; i <= n; i++) {
        int costPrev1 = prev1 + cost[i - 1];
        int costPrev2 = prev2 + cost[i - 2];
        curr = Math.min(costPrev1, costPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return curr;
}

