public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null) {
        return false;
    }
    if (k <= 0) {
        // By definition all binary strings of length 0 (empty string) are present
        return true;
    }

    int n = s.length();
    int totalCodes = 1 << k;

    // Quick check: if the string is shorter than the number of
    // possible k-length binary strings, it cannot contain them all
    if (n < totalCodes) {
        return false;
    }

    boolean[] seen = new boolean[totalCodes];
    int code = 0;
    int mask = totalCodes - 1;

    // Build the first code from the first k characters
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;

    // Slide over the string, updating the code in O(1) time
    for (int i = k; i < n; i++) {
        code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == totalCodes) {
                return true; // Early exit if all codes are found
            }
        }
    }

    return count == totalCodes;
}

