    }
    int n = s.length();
    // Calculate number of possible codes, guard against overflow
    if (k >= 31) { // 1 << k would overflow an int
        return false;
    }
    int maxCodes = 1 << k;
    if (n < maxCodes) {
        return false;
    }
    boolean[] seen = new boolean[maxCodes];
    int mask = maxCodes - 1;
    int val = 0;
