    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen[val] = true;
    int uniqueCount = 1;
    // Slide window
    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[val]) {
            seen[val] = true;
            uniqueCount++;
            if (uniqueCount == maxCodes) {
                return true;
            }
        }
    }
    return uniqueCount == maxCodes;
}

