public int minOperations(int n) {
    if (n <= 1) {
        return 0;
    }
    long s = (long) (n + 1) / 2;   // ceil(n/2)
    long m = n - s;
    long ops = s * m;
    return (int) ops;
}

public int minOperations(int n) {
    // If n is non-positive, no operations are needed
    if (n <= 0) {
        return 0;
    }
    // Compute m = floor((n + 1) / 2), k = n - m
    int m = (n + 1) / 2;
    int k = n - m;
    // Use long to avoid overflow in intermediate multiplication
    long ops = (long) m * k;
    // The result fits into an int by problem constraints
    return (int) ops;
}

