public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (n % 2 == 0) { // even
        int t = n / 2;
        return t * t;
    } else { // odd
        int t = (n - 1) / 2;
        return t * (t + 1);
    }
}

public int minOperations(int n) {
    if (n <= 1) {
        return 0; // nothing to do
    }
    long count = n / 2L;                // number of surplus (or deficit) elements
    long a = n - count;                 // starting index of surplus
    long sumIndices = n * (n - 1L) / 2L; // sum of all indices 0..n-1
    long sumBeforeA = (a - 1L) * a / 2L; // sum of indices 0..a-1
    long sumIndicesSurplus = sumIndices - sumBeforeA;
    long sum2i = 2L * sumIndicesSurplus; // sum of 2i over surplus indices
    long sumOnes = count;                // number of +1 terms
    long surplusSum = sum2i + sumOnes - n * count;
    return (int) surplusSum;
}

