                }
            }
        }
        // Combine low factors followed by the reverse of high factors to maintain ascending order
        int totalFactors = lowFactors.size() + highFactors.size();
        if (k > totalFactors) {
            return -1;
        }
        // If k is within low factors
        if (k <= lowFactors.size()) {
            return lowFactors.get(k - 1);
        } else {
            // Adjust index for high factors part
            int indexInHigh = k - lowFactors.size() - 1;
            // highFactors are in decreasing order, so get from the end
            return highFactors.get(indexInHigh);
        }
