            smallFactors.add(i);
            int other = n / i;
            if (other != i) {
                largeFactors.add(other);
            }
        }
    }

    // largeFactors currently in increasing order, but the factors should be appended in reverse
    int totalFactors = smallFactors.size() + largeFactors.size();
    if (k > totalFactors) {
        return -1;
    }

    if (k <= smallFactors.size()) {
        return smallFactors.get(k - 1);
