        // k-th factor is in largeFactors reversed
        int indexInLarge = largeFactors.size() - (k - smallFactors.size());
        return largeFactors.get(indexInLarge);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = sb.length();
        if (len > 0) {
            char last = sb.charAt(len - 1);
            if (Math.abs(c - last) == 32) {
                sb.deleteCharAt(len - 1);
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

