        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(c - last) == 32) { // same letter, opposite case
                stack.setLength(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

