public String getSmallestString(int n, int k) {
    if (n < 0 || k < 0) {
        return "";
    }
    // The minimum sum is n (all 'a's) and the maximum is 26*n (all 'z's)
    if (k < n || k > 26 * n) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // 'a' to 'z', max +25
        sb.setCharAt(i, (char) (sb.charAt(i) + add));
        remaining -= add;
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive");
    }
    int minPossible = n;          // all 'a's
    int maxPossible = 26 * n;     // all 'z's
    if (k < minPossible || k > maxPossible) {
        throw new IllegalArgumentException("k is out of possible range");
    }

    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // how many extra points we need to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int increment = Math.min(25, remaining); // each position can go up by at most 25
        result[i] = (char) ('a' + increment);
        remaining -= increment;
    }

    return new String(result);
}

