public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int result = 0;
    for (int bit = 0; bit < 32; bit++) {
        int bitCount = 0;
        int mask = 1 << bit;
        for (int num : nums) {
            if ((num & mask) != 0) {
                bitCount++;
            }
        }
        if (bitCount % 3 != 0) {
            result |= mask;
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty.");
    }
    int[] bitCount = new int[32];
    try {
        for (int num : nums) {
            for (int i = 0; i < 32; i++) {
                bitCount[i] += (num >> i) & 1;
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error while processing the array.", e);
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        // Bits that are set in both ones and num contribute to twos
        twos |= ones & num;
        // Toggle bits that appear an odd number of times
        ones ^= num;
        // Remove bits that have appeared three times
        int commonMask = ones & twos;
        ones &= ~commonMask;
        twos &= ~commonMask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        // Update 'ones' with bits that have appeared 1 or 4 times so far
        int newOnes = (ones ^ num) & ~twos;
        // Update 'twos' with bits that have appeared 2 or 3 times so far
        int newTwos = (twos ^ num) & ~newOnes;
        ones = newOnes;
        twos = newTwos;
    }
    return ones;
}

