    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >>> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= 1 << i;
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    // Handle invalid range
    if (low > high) {
        return new ArrayList<>();
    }

    // Ensure low is at least 0 (stepping numbers are non-negative integers)
    if (low < 0) {
        low = 0;
    }

    TreeSet<Integer> resultSet = new TreeSet<>();

    // Explore starting digits from 0 to 9
    for (int startingDigit = 0; startingDigit <= 9; startingDigit++) {
        if (startingDigit > high) {
            break; // no need to process larger starting digits
        }

        Queue<Long> queue = new LinkedList<>();
        queue.offer((long) startingDigit);

        while (!queue.isEmpty()) {
            long current = queue.poll();

            if (current > high) {
                continue; // prune branches that exceed the upper bound
            }

            if (current >= low) {
                resultSet.add((int) current);
            }

            // Do not generate further numbers if current is 0 to avoid redundant paths like 0 -> 1 -> 0?
            // It's safe to continue; the algorithm will naturally avoid duplicates due to the set.
            long lastDigit = current % 10;

            // Extend the number by adding a new digit that is one less than the last digit
            if (lastDigit > 0) {
                long next = current * 10 + (lastDigit - 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }

            // Extend the number by adding a new digit that is one more than the last digit
            if (lastDigit < 9) {
                long next = current * 10 + (lastDigit + 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }
        }
    }

    return new ArrayList<>(resultSet);
}

