    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;
    try {
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                    vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                    diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                    anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                    int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                            Math.max(diag[i][j], anti[i][j]));
                    if (localMax > max) {
                        max = localMax;
                    }
                }
            }
        }
    } catch (Exception e) {
        // In case of any runtime issues (e.g., irregular matrix shape), return 0
        return 0;
    }
    return max;
}

public static int longestLine(int[][] mat) {
    // Handle null or empty input
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;

    // DP arrays: each cell stores the consecutive 1s in 4 directions
    // dir0: horizontal (left to right)
    // dir1: vertical (top to bottom)
    // dir2: diagonal (top-left to bottom-right)
    // dir3: anti-diagonal (top-right to bottom-left)
    int[][][] dp = new int[m][n][4];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        // Handle rows of varying length safely
        if (mat[i] == null) {
            continue;
        }
        for (int j = 0; j < mat[i].length && j < n; j++) {
            if (mat[i][j] != 1) {
                continue;
            }
            // Horizontal
            dp[i][j][0] = 1 + (j > 0 ? dp[i][j - 1][0] : 0);
            // Vertical
            dp[i][j][1] = 1 + (i > 0 ? dp[i - 1][j][1] : 0);
            // Diagonal
            dp[i][j][2] = 1 + (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0);
            // Anti-diagonal
            dp[i][j][3] = 1 + (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0);

            int currentMax = dp[i][j][0];
            currentMax = Math.max(currentMax, dp[i][j][1]);
            currentMax = Math.max(currentMax, dp[i][j][2]);
            currentMax = Math.max(currentMax, dp[i][j][3]);
            if (currentMax > maxLen) {
                maxLen = currentMax;
            }
        }
    }

    return maxLen;
}

