public static int longestLine(int[][] mat) {
    try {
        if (mat == null || mat.length == 0) {
            return 0;
        }
        int m = mat.length;
        int n = mat[0].length;
        if (n == 0) {
            return 0;
        }
        // Validate the matrix dimensions
        for (int i = 0; i < m; i++) {
            if (mat[i] == null || mat[i].length != n) {
                return 0; // malformed input
            }
        }

        int max = 0;
        int[][] diag = new int[m][n];   // main diagonal (↘)
        int[][] anti = new int[m][n];   // anti diagonal (↙)
        int[] col = new int[n];         // vertical count per column

        for (int i = 0; i < m; i++) {
            int horiz = 0; // horizontal count for current row
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    horiz++;
                    col[j]++;
                    diag[i][j] = (i > 0 && j > 0) ? diag[i - 1][j - 1] + 1 : 1;
                    anti[i][j] = (i > 0 && j < n - 1) ? anti[i - 1][j + 1] + 1 : 1;

                    int currMax = horiz;
                    if (col[j] > currMax) currMax = col[j];
                    if (diag[i][j] > currMax) currMax = diag[i][j];
                    if (anti[i][j] > currMax) currMax = anti[i][j];

                    if (currMax > max) {
                        max = currMax;
                    }
                } else {
                    horiz = 0;
                    col[j] = 0;
                    diag[i][j] = 0;
                    anti[i][j] = 0;
                }
            }
        }
        return max;
    } catch (Exception e) {
        return 0;
    }
}

public static String addThousandSeparator(int n) {
    // Handle zero straight away
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    // Work with absolute value to simplify processing
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (value > 0) {
        sb.append(value % 10);
        value /= 10;
        digitCount++;
        if (value > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    // If negative, add minus sign
    if (negative) {
        sb.append('-');
    }
    // The string is built in reverse order, reverse it to correct
    return sb.reverse().toString();
}

