public static int squarePermutations(int[] A) {
    int n = A.length;
    int fullMask = (1 << n) - 1;
    // Precompute square status up to max possible sum
    int maxVal = 0;
    for (int v : A) maxVal = Math.max(maxVal, v);
    int maxSum = maxVal + maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // adjacency matrix
    boolean[][] ok = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                ok[i][j] = isSquare[A[i] + A[j]];
            }
        }
    }
    // DP memo: dp[mask][lastIndex+1]
    long[][] memo = new long[1 << n][n + 1];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1L);
    }
    java.util.Arrays.sort(A); // sort to facilitate duplicate skipping
    java.util.Map<Integer, Integer> origIndices = new java.util.HashMap<>();
    for (int i = 0; i < n; i++) {
        origIndices.put(i, i); // not needed
    }
    // But we must keep original relative order after sorting for ok matrix? 
    // Sorting changes indices and adjacency. We need to keep original indices.
    // Instead, use original array but sort a helper for skip logic:
    int[] sorted = A.clone();
    java.util.Arrays.sort(sorted);
    java.util.Map<Integer, java.util.List<Integer>> valueToIndices = new java.util.HashMap<>();
    for (int i = 0; i < n; i++) {
        valueToIndices.computeIfAbsent(A[i], k -> new java.util.ArrayList<>()).add(i);
    }
    // Recursive function
    java.util.function.LongBinaryOperator dfs = null;
    dfs = (mask, lastIdx) -> {
        if (mask == fullMask) return 1L;
        long &mp = memo[mask][lastIdx + 1];
        if (mp != -1L) return mp;
        long res = 0L;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) continue;
            if (lastIdx != -1 && !ok[lastIdx][i]) continue;
            // skip duplicates
            if (i > 0 && A[i] == A[i - 1] && ((mask & (1 << (i - 1))) == 0)) continue;
            res += dfs.applyAsLong(mask | (1 << i), i);
        }
        memo[mask][lastIdx + 1] = res;
        return res;
    };
    return (int) dfs.applyAsLong(0, -1);
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = A.length;
    if (n == 0) {
        return 0;
    }
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    return backtrack(A, used, -1);
}

private static int backtrack(int[] A, boolean[] used, int prevIndex) {
    int n = A.length;
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (used[i]) {
            continue;
        }
        // Skip duplicate values to avoid counting identical permutations
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) {
            continue;
        }
        if (prevIndex == -1 || isPerfectSquare(A[prevIndex] + A[i])) {
            used[i] = true;
            if (isComplete(used)) {
                count++;
            } else {
                count += backtrack(A, used, i);
            }
            used[i] = false;
        }
    }
    return count;
}

private static boolean isComplete(boolean[] used) {
    for (boolean b : used) {
        if (!b) {
            return false;
        }
    }
    return true;
}

private static boolean isPerfectSquare(int sum) {
    int sqrt = (int) Math.round(Math.sqrt(sum));
    return sqrt * sqrt == sum;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;
    int n = A.length;
    // Build frequency map of unique values
    java.util.Map<Integer, Integer> valCountMap = new java.util.HashMap<>();
    for (int num : A) {
        valCountMap.put(num, valCountMap.getOrDefault(num, 0) + 1);
    }
    int m = valCountMap.size(); // number of unique values
    int[] vals = new int[m];
    int[] counts = new int[m];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : valCountMap.entrySet()) {
        vals[idx] = e.getKey();
        counts[idx] = e.getValue();
        idx++;
    }
    // Precompute perfect squares up to 2*maxVal
    int maxVal = 0;
    for (int v : vals) if (v > maxVal) maxVal = v;
    int maxSum = 2 * maxVal;
    java.util.Set<Integer> squares = new java.util.HashSet<>();
    for (int k = 1; k * k <= maxSum; k++) {
        squares.add(k * k);
    }
    // Build adjacency list
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
    for (int i = 0; i < m; i++) {
        java.util.List<Integer> list = new java.util.ArrayList<>();
        for (int j = 0; j < m; j++) {
            if (squares.contains(vals[i] + vals[j])) {
                list.add(j);
            }
        }
        adj.add(list);
    }
    java.util.HashMap<Long, Integer> memo = new java.util.HashMap<>();
    java.util.function.LongBinaryOperator keyMaker = (countsArrKey, lastIdx) -> {
        long key = countsArrKey | ((long)lastIdx << (4 * m));
        return key;
    };
    // Pack counts into a long key part
    java.util.function.IntUnaryOperator packCounts = (unused) -> {
        long key = 0;
        for (int i = 0; i < m; i++) {
            key |= ((long)(counts[i] & 0xF)) << (4 * i);
        }
        return (int)key; // actually we will keep long
    };
    // Use recursive DFS closure
    java.util.function.Function<java.lang.Object, Integer> dfs = new java.util.function.Function<java.lang.Object, Integer>() {
        @Override
        public Integer apply(Object param) {
            int lastIdx = (int) param;
            long countsKey = 0;
            for (int i = 0; i < m; i++) {
                countsKey |= ((long)(counts[i] & 0xF)) << (4 * i);
            }
            long memoKey = countsKey | ((long)lastIdx << (4 * m));
            Integer memoVal = memo.get(memoKey);
            if (memoVal != null) return memoVal;
            // Check if all counts zero
            boolean done = true;
            for (int c : counts) {
                if (c != 0) {
                    done = false;
                    break;
                }
            }
            if (done) return 1;
            long total = 0;
            for (int nextIdx : adj.get(lastIdx)) {
                if (counts[nextIdx] == 0) continue;
                counts[nextIdx]--;
                total += dfs.apply(nextIdx);
                counts[nextIdx]++; // backtrack
                if (total > Integer.MAX_VALUE) total %= Integer.MAX_VALUE; // guard overflow
            }
            memo.put(memoKey, (int) total);
            return (int) total;
        }
    };
    long result = 0;
    for (int i = 0; i < m; i++) {
        if (counts[i] == 0) continue;
        counts[i]--;
        result += dfs.apply(i);
        counts[i]++;
    }
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);
    boolean[] used = new boolean[n];
    java.util.Arrays.fill(used, false);
    java.util.HashMap<Long, Integer> memo = new java.util.HashMap<>();

    // Precompute which pairs have perfect square sums
    boolean[][] ok = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = arr[i] + arr[j];
            int r = (int) Math.sqrt(sum);
            ok[i][j] = (r * r == sum);
        }
    }

    long backtrack(int depth, int lastIdx) {
        if (depth == n) return 1L;
        long key = (((long) lastIdx) << 32) | getMask(used);
        Integer cached = memo.get(key);
        if (cached != null) return cached;
        long count = 0;
        for (int i = 0; i < n; i++) {
            if (used[i]) continue;
            if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue; // skip duplicates
            if (lastIdx != -1 && !ok[lastIdx][i]) continue;
            used[i] = true;
            count += backtrack(depth + 1, i);
            used[i] = false;
        }
        memo.put(key, (int) count);
        return count;
    }

    // Helper to encode used array mask into a long
    long getMask(boolean[] usedArr) {
        long mask = 0L;
        for (int i = 0; i < usedArr.length; i++) {
            if (usedArr[i]) mask |= (1L << i);
        }
        return mask;
    }

    long result = backtrack(0, -1);
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    int maxArea = 0;
    int i = 0;
    int n = heights.length;
    while (i < n) {
        if (stack.isEmpty() || heights[i] >= heights[stack.peek()]) {
            stack.push(i);
            i++;
        } else {
            int topIndex = stack.pop();
            int height = heights[topIndex];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = (int) area;
            }
        }
    }
    while (!stack.isEmpty()) {
        int topIndex = stack.pop();
        int height = heights[topIndex];
        int width = stack.isEmpty() ? i : i - stack.peek() - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = (int) area;
        }
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0;
    int n = heights.length;
    for (int i = 0; i <= n; i++) {
        long currentHeight = (i == n) ? 0 : heights[i];
        if (currentHeight < 0) {
            throw new IllegalArgumentException("Heights must be non-negative");
        }
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return (int) maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    // Validate input: heights must be non-negative
    for (int h : heights) {
        if (h < 0) {
            throw new IllegalArgumentException("Bar heights must be non-negative.");
        }
    }

    int n = heights.length;
    // Stack to keep indices of histogram bars
    int[] stack = new int[n + 1]; // +1 for sentinel handling
    int top = -1;
    long maxArea = 0;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];

        // Pop bars from stack while the current bar is lower than the bar at stack top
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];  // Pop
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }

    return (int) maxArea;
}

