public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(-1); // sentinel to simplify width calculation
    long maxArea = 0;
    try {
        for (int i = 0; i < heights.length; i++) {
            while (!stack.isEmpty() && stack.peek() != -1 && heights[i] < heights[stack.peek()]) {
                int height = heights[stack.pop()];
                int width = i - stack.peek() - 1;
                long area = (long) height * width;
                if (area > maxArea) {
                    maxArea = area;
                }
            }
            stack.push(i);
        }
        // Process remaining bars in stack
        while (stack.size() > 1) { // sentinel -1 remains
            int height = heights[stack.pop()];
            int width = heights.length - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
    } catch (Exception e) {
        // In case of unexpected runtime issues, return 0 as fallback
        return 0;
    }
    return (int) Math.min(maxArea, Integer.MAX_VALUE);
}

