public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int totalDiagonals = m + n - 1;
    for (int sum = 0; sum < totalDiagonals; sum++) {
        if (sum % 2 == 0) {
            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[index++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[index++] = mat[i][j];
                j--;
                i++;
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    // Handle invalid or empty input
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int index = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startCol = Math.max(0, sum - (m - 1));
        int endCol = Math.min(n - 1, sum);
        if ((sum & 1) == 0) { // even sum -> reverse the order
            for (int col = endCol; col >= startCol; col--) {
                result[index++] = mat[sum - col][col];
            }
        } else { // odd sum -> normal order
            for (int col = startCol; col <= endCol; col++) {
                result[index++] = mat[sum - col][col];
            }
        }
    }
    return result;
}

