public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] charDigits = Integer.toString(n).toCharArray();
    int len = charDigits.length;
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = charDigits[i] - '0';
    }

    // Find the longest non-increasing suffix
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) { // digits are in descending order => no greater permutation
        return -1;
    }

    // Find the rightmost successor to pivot in the suffix
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the pivot with its successor
    int tmp = digits[i];
    digits[i] = digits[j];
    digits[j] = tmp;

    // Reverse the suffix
    int left = i + 1, right = len - 1;
    while (left < right) {
        tmp = digits[left];
        digits[left] = digits[right];
        digits[right] = tmp;
        left++;
        right--;
    }

    // Construct the result and check bounds
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
        if (result > Integer.MAX_VALUE) {
            return -1; // would overflow int
        }
    }
    if (result <= n) {
        return -1; // should always be larger, but safeguard
    }
    return (int) result;
}

