public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    try {
        char[] arr = new char[n];
        backtrack(result, arr, 0, n - 1);
    } catch (Exception e) {
        // Return what has been collected so far in case of error
    }
    java.util.Collections.sort(result);
    return result;
}

private static void backtrack(java.util.List<String> res, char[] arr, int left, int right) {
    if (left > right) {
        res.add(new String(arr));
        return;
    }
    if (left == right) {
        char[] middle = {'0', '1', '8'};
        for (char c : middle) {
            arr[left] = c;
            res.add(new String(arr));
        }
        return;
    }
    char[][] pairs = {
        {'0', '0'},
        {'1', '1'},
        {'6', '9'},
        {'8', '8'},
        {'9', '6'}
    };
    for (char[] p : pairs) {
        if (left == 0 && p[0] == '0') {
            continue; // leading zero is not allowed
        }
        arr[left] = p[0];
        arr[right] = p[1];
        backtrack(res, arr, left + 1, right - 1);
    }
}

