public static List<String> centerSymmetricNumbers(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Length must be non-negative");
    }
    List<String> result = new ArrayList<>();
    if (n == 0) {
        return result; // no numbers of length 0
    }
    // Helper lambda recursion
    java.util.function.BiFunction<Integer, Integer, List<String>> build = new java.util.function.BiFunction<>() {
        @Override
        public List<String> apply(Integer len, Integer originalLen) {
            List<String> list = new ArrayList<>();
            if (len == 0) {
                list.add("");
                return list;
            }
            if (len == 1) {
                list.add("0");
                list.add("1");
                list.add("8");
                return list;
            }
            List<String> sub = apply(len - 2, originalLen);
            char[][] pairs = { {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'} };
            for (char[] pair : pairs) {
                if (len == originalLen && pair[0] == '0') {
                    continue; // avoid leading zero for top-level
                }
                for (String s : sub) {
                    list.add(pair[0] + s + pair[1]);
                }
            }
            return list;
        }
    };
    result = build.apply(n, n);
    return result;
}

