private static void backtrack(char[] cur, char[][] pairs, int left, int right, java.util.List<String> result) {
    if (left > right) {
        result.add(new String(cur));
        return;
    }
    if (left == right) {
        for (char[] p : pairs) {
            if (p[0] == p[1]) {
                cur[left] = p[0];
                result.add(new String(cur));
            }
        }
        return;
    }
    for (char[] p : pairs) {
        if (left == 0 && p[0] == '0') {
            continue; // avoid leading zero
        }
        cur[left] = p[0];
        cur[right] = p[1];
        backtrack(cur, pairs, left + 1, right - 1, result);
    }
}

