                    return false;
                }
            }
        }
        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];
        // compute cross product of vectors (p2-p1) and (p3-p1)
        int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        return cross != 0;
    } catch (Exception e) {
        // on any unexpected error return false
        return false;
    }
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length < 3) {
        return false;
    }
    // We only need exactly 3 points for a boomerang
    if (points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length < 2) {
            return false;
        }
    }
    try {
        long x1 = points[0][0];
        long y1 = points[0][1];
        long x2 = points[1][0];
        long y2 = points[1][1];
        long x3 = points[2][0];
        long y3 = points[2][1];

        // Calculate cross product to check collinearity:
        // (x2 - x1)*(y3 - y1) - (x3 - x1)*(y2 - y1)
        long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        return cross != 0;
    } catch (Exception e) {
        // Any unexpected exception (e.g., ArrayIndexOutOfBounds) results in false
        return false;
    }
}

