public static int calculateEnergy(String s) {
    // Return 0 if the input is null or empty, treating it as having no valid substrings.
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;      // At least one character forms a substring of length 1.
    int currentCount = 1;   // Count of the current streak of identical characters.

    // Iterate through the string starting from the second character.
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            // Same character as previous, extend the current streak.
            currentCount++;
        } else {
            // Different character, end current streak and reset counter.
            if (currentCount > maxEnergy) {
                maxEnergy = currentCount;
            }
            currentCount = 1;
        }
    }

    // Final check in case the longest streak is at the end of the string.
    if (currentCount > maxEnergy) {
        maxEnergy = currentCount;
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    // List to store the result
    java.util.List<Integer> result = new java.util.ArrayList<>(n);
    if (n <= 0) {
        return result; // return empty list for non-positive n
    }
    int current = 1; // start from the first number
    while (result.size() < n) {
        result.add(current);
        if (current * 10 <= n) {
            // go deeper into the next level of the lexicographic tree
            current *= 10;
        } else {
            // if we cannot go deeper, move to the next sibling or ancestor
            if (current % 10 != 9 && current + 1 <= n) {
                current++;
            } else {
                while (current % 10 == 9 && current / 10 != 0) {
                    current /= 10;
                }
                current = current / 10 + 1;
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long cur = 1;
    long limit = n;
    for (int i = 0; i < n; i++) {
        result.add((int) cur);
        if (cur * 10 <= limit) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= limit) {
            cur++;
        } else {
            while (cur / 10 % 10 == 9 || cur + 1 > limit) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result; // or throw IllegalArgumentException("n must be positive");
    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    result.add(current);
    if (current > n / 10) {
        return; // no further children will be <= n
    }
    int base = current * 10;
    for (int d = 0; d <= 9; d++) {
        int next = base + d;
        if (next > n) {
            break;
        }
        dfs(next, n, result);
    }
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    while (result.size() < n) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static java.util.List<Integer> lexicalOrder(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    java.util.ArrayList<Integer> result = new java.util.ArrayList<>(n);
    int cur = 1;
    try {
        for (int i = 0; i < n; i++) {
            result.add(cur);
            if ((long) cur * 10 <= n) {
                cur *= 10;
            } else {
                while (cur % 10 == 9 || (long) cur + 1 > n) {
                    cur /= 10;
                }
                cur += 1;
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error generating lexical order", e);
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

