    }
    int[] dp = new int[n + 1];
    // Initialize with large values; dp[0] is zero
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }
    if (n == 0) {
        return 0;
    }

    // Check if n itself is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }

    // Leverage Legendre's three-square theorem to quickly determine the answer
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }

    // Check if n can be expressed as the sum of two perfect squares
    for (int i = 1; i <= sqrtN; i++) {
        int remaining = n - i * i;
        int sqrtRem = (int) Math.sqrt(remaining);
        if (sqrtRem * sqrtRem == remaining) {
            return 2;
        }
    }

    // If not 1, 2, or 4, the answer must be 3
    return 3;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input n must be non‑negative");
    }
    if (n == 0) {
        return 0;
    }

    try {
        int[] dp = new int[n + 1];
        dp[0] = 0;
        // Initialize dp array with a large number
        for (int i = 1; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j * j <= i; j++) {
                int square = j * j;
                if (dp[i - square] + 1 < dp[i]) {
                    dp[i] = dp[i - square] + 1;
                }
            }
        }
        return dp[n];
    } catch (OutOfMemoryError e) {
        // In case the input is too large for the memory allocation
        throw new IllegalArgumentException("Input is too large to process", e);
    }
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    result.append(word.reverse());
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
